1	import { db } from "@/lib/db";
2	
3	/**
4	 * Server-side helpers for the deploy-wizard funnel (DeployFunnelEvent).
5	 *
6	 * Two concerns live here:
7	 *  1. WRITE — `recordDeployFunnelError` / `recordDeployFunnelComplete` let the
8	 *     authoritative server paths (the payAndDeploy action, the order/provision
9	 *     code) stamp an error/complete event even when the browser never sees the
10	 *     outcome. Both are strictly best-effort: they swallow every failure so they
11	 *     can never disturb the money path they're instrumenting.
12	 *  2. READ — `deployFunnels` aggregates the raw events into the admin funnel view:
13	 *     per product, per step, how many REACHED it, how many of those COMPLETED the
14	 *     deploy, how many DROPPED OFF, and how many ERRORED (with the top error
15	 *     messages) — so an admin can tell "stuck on a BUG" from "just abandoned".
16	 */
17	
18	const DAY = 86_400_000;
19	const EVENT_CAP = 100_000;
20	
21	export type DeployProduct = "vps" | "game" | "hosting" | "email";
22	
23	/**
24	 * Typed accessor for the DeployFunnelEvent delegate.
25	 *
26	 * The generated Prisma client in this worktree does not yet carry this model
27	 * (its node_modules is symlinked to prod, which we must not regenerate here — the
28	 * owner regenerates the client when they apply prisma/manual-migration-deploy-funnel.sql
29	 * at deploy). This shim types every read/write against the model's real shape so
30	 * call sites stay type-safe and `tsc` is clean now, and binds to the genuine
31	 * delegate the moment the client is regenerated. It is the ONLY place that reaches
32	 * for the delegate, so there is a single seam to delete once the model is generated.
33	 */
34	export type DeployFunnelEventRow = {
35	  id: string;
36	  userId: string | null;
37	  visitorId: string | null;
38	  sessionId: string | null;
39	  product: string;
40	  step: string;
41	  stepIndex: number;
42	  type: string;
43	  errorCode: string | null;
44	  errorMessage: string | null;
45	  createdAt: Date;
46	};
47	
48	type DeployFunnelDelegate = {
49	  create(args: { data: Partial<DeployFunnelEventRow> }): Promise<DeployFunnelEventRow>;
50	  findMany(args: {
51	    where?: Record<string, unknown>;
52	    select?: Record<string, boolean>;
53	    take?: number;
54	    orderBy?: Record<string, "asc" | "desc">;
55	  }): Promise<DeployFunnelEventRow[]>;
56	};
57	
58	function dfe(): DeployFunnelDelegate {
59	  return (db as unknown as { deployFunnelEvent: DeployFunnelDelegate }).deployFunnelEvent;
60	}
61	
62	/** Low-level insert used by the /api/track/deploy-step route (and internally).
63	 *  Fire-and-forget; never throws. */
64	export async function insertDeployFunnelEvent(data: Partial<DeployFunnelEventRow>): Promise<void> {
65	  try {
66	    await dfe().create({ data });
67	  } catch {
68	    /* best-effort analytics — never disturb the caller */
69	  }
70	}
71	
72	/** Record a deploy failure server-side. Fire-and-forget; never throws. */
73	export async function recordDeployFunnelError(input: {
74	  product: DeployProduct;
75	  step: string;
76	  stepIndex: number;
77	  errorCode: string;
78	  errorMessage?: string | null;
79	  userId?: string | null;
80	}): Promise<void> {
81	  await insertDeployFunnelEvent({
82	    product: input.product,
83	    step: input.step.slice(0, 60),
84	    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
85	    type: "error",
86	    errorCode: input.errorCode.slice(0, 60),
87	    errorMessage: input.errorMessage ? input.errorMessage.slice(0, 300) : null,
88	    userId: input.userId ?? null,
89	  });
90	}
91	
92	/** Record a successful deploy server-side. Fire-and-forget; never throws. */
93	export async function recordDeployFunnelComplete(input: {
94	  product: DeployProduct;
95	  step: string;
96	  stepIndex: number;
97	  userId?: string | null;
98	}): Promise<void> {
99	  await insertDeployFunnelEvent({
100	    product: input.product,
101	    step: input.step.slice(0, 60),
102	    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
103	    type: "complete",
104	    userId: input.userId ?? null,
105	  });
106	}
107	
108	// ---- Read side: aggregate events into the funnel view ----
109	
110	export type ErrorTally = { code: string | null; message: string | null; count: number };
111	
112	export type FunnelStep = {
113	  step: string;
114	  /** Ordering position (min observed stepIndex for this step within the product). */
115	  order: number;
116	  /** Distinct sessions that reached this step. */
117	  reached: number;
118	  /** Of those, how many ultimately completed the deploy. */
119	  completedThrough: number;
120	  /** Distinct sessions that dropped off AT this step (reached here, not the next). */
121	  abandoned: number;
122	  /** Drop-off share at this step (abandoned / reached), 0..1. */
123	  dropOffRate: number;
124	  /** Distinct sessions that hit an error on this step. */
125	  erroredSessions: number;
126	  /** Total error events on this step (a session can error more than once). */
127	  errorEvents: number;
128	  /** Most common error codes/messages on this step. */
129	  topErrors: ErrorTally[];
130	};
131	
132	export type ProductFunnel = {
133	  product: DeployProduct;
134	  /** Distinct sessions that reached the first step (top of funnel). */
135	  started: number;
136	  /** Distinct sessions with a completed deploy. */
137	  completed: number;
138	  /** Distinct sessions that errored anywhere. */
139	  erroredSessions: number;
140	  steps: FunnelStep[];
141	};
142	
143	/** Stable identity for one wizard run: session, else visitor, else account, else row. */
144	function identity(e: { sessionId: string | null; visitorId: string | null; userId: string | null; id: string }): string {
145	  return e.sessionId ?? e.visitorId ?? e.userId ?? e.id;
146	}
147	
148	const PRODUCTS: DeployProduct[] = ["vps", "game", "hosting", "email"];
149	
150	/**
151	 * Build the per-product deploy funnel over the trailing `days` window. Read-only,
152	 * window-scoped and take-capped so it stays cheap as the event log grows.
153	 */
154	export async function deployFunnels(days = 30): Promise<ProductFunnel[]> {
155	  const since = new Date(Date.now() - days * DAY);
156	  const events = await dfe().findMany({
157	    where: { createdAt: { gte: since } },
158	    select: {
159	      id: true,
160	      product: true,
161	      step: true,
162	      stepIndex: true,
163	      type: true,
164	      errorCode: true,
165	      errorMessage: true,
166	      sessionId: true,
167	      visitorId: true,
168	      userId: true,
169	    },
170	    take: EVENT_CAP,
171	    orderBy: { createdAt: "desc" },
172	  });
173	
174	  const out: ProductFunnel[] = [];
175	
176	  for (const product of PRODUCTS) {
177	    const rows = events.filter((e) => e.product === product);
178	    if (rows.length === 0) continue;
179	
180	    // Which runs completed the deploy (for completed-through per step + the
181	    // top-of-card completed count).
182	    //
183	    // IDENTITY RECONCILIATION. Completion is now recorded AUTHORITATIVELY on the
184	    // server (the shared placeOrder / placeGameOrder / placeHostingOrder success
185	    // paths — see lib/deploy-funnel `recordDeployFunnelComplete`), where the only
186	    // stable handle is the signed-in `userId`: a webhook-driven card fulfilment has
187	    // no browser session. The wizard's own `step` beacons, by contrast, key on the
188	    // per-tab `sessionId`. So a completion and the steps that led to it resolve to
189	    // DIFFERENT `identity()` strings, and matching purely on identity would report
190	    // every completed session as "abandoned at the last step". We therefore match a
191	    // completion to its run by `userId` (every deploy requires login, so both sides
192	    // carry one), falling back to identity for any legacy client-side complete that
193	    // had no account attributed.
194	    const completedUserIds = new Set<string>();
195	    const completedIdentityIds = new Set<string>();
196	    for (const e of rows) {
197	      if (e.type !== "complete") continue;
198	      if (e.userId) completedUserIds.add(e.userId);
199	      else completedIdentityIds.add(identity(e));
200	    }
201	    // identity → the account that owns that run, so a `sessionId`-keyed step can be
202	    // tied back to a `userId`-keyed completion. First non-null userId per identity.
203	    const userOf = new Map<string, string>();
204	
205	    // Per-step aggregation.
206	    type Acc = {
207	      order: number;
208	      reached: Set<string>;
209	      errored: Set<string>;
210	      errorEvents: number;
211	      errors: Map<string, { code: string | null; message: string | null; count: number }>;
212	    };
213	    const byStep = new Map<string, Acc>();
214	    const erroredAnywhere = new Set<string>();
215	
216	    const ensure = (step: string, stepIndex: number): Acc => {
217	      let a = byStep.get(step);
218	      if (!a) {
219	        a = { order: stepIndex, reached: new Set(), errored: new Set(), errorEvents: 0, errors: new Map() };
220	        byStep.set(step, a);
221	      } else if (stepIndex < a.order) {
222	        a.order = stepIndex; // keep the earliest observed position for ordering
223	      }
224	      return a;
225	    };
226	
227	    for (const e of rows) {
228	      const id = identity(e);
229	      if (e.userId && !userOf.has(id)) userOf.set(id, e.userId);
230	      if (e.type === "step") {
231	        ensure(e.step, e.stepIndex).reached.add(id);
232	      } else if (e.type === "error") {
233	        const a = ensure(e.step, e.stepIndex);
234	        a.errored.add(id);
235	        a.errorEvents += 1;
236	        erroredAnywhere.add(id);
237	        const key = `${e.errorCode ?? ""}�${e.errorMessage ?? ""}`;
238	        const cur = a.errors.get(key) ?? { code: e.errorCode, message: e.errorMessage, count: 0 };
239	        cur.count += 1;
240	        a.errors.set(key, cur);
241	      }
242	    }
243	
244	    const ordered = [...byStep.entries()]
245	      .map(([step, a]) => ({ step, a }))
246	      .sort((x, y) => x.a.order - y.a.order || x.step.localeCompare(y.step));
247	
248	    // Did the run behind this step identity complete? By userId (the authoritative
249	    // server-side key) first, then a direct identity hit for legacy client completes.
250	    const runCompleted = (id: string): boolean => {
251	      if (completedIdentityIds.has(id)) return true;
252	      const u = userOf.get(id);
253	      return u != null && completedUserIds.has(u);
254	    };
255	
256	    // Distinct completed runs: accounts that completed, plus any accountless legacy
257	    // completion. The two sets are disjoint by construction.
258	    const completed = completedUserIds.size + completedIdentityIds.size;
259	
260	    const steps: FunnelStep[] = ordered.map(({ step, a }, i) => {
261	      const reached = a.reached.size;
262	      const next = ordered[i + 1];
263	      // Sessions continuing past this step = reached the next step (or, on the last
264	      // step, completed the deploy). Everyone else abandoned here.
265	      const continued = next
266	        ? [...a.reached].filter((id) => next.a.reached.has(id)).length
267	        : [...a.reached].filter((id) => runCompleted(id)).length;
268	      const abandoned = Math.max(0, reached - continued);
269	      const completedThrough = [...a.reached].filter((id) => runCompleted(id)).length;
270	      const topErrors = [...a.errors.values()].sort((p, q) => q.count - p.count).slice(0, 3);
271	      return {
272	        step,
273	        order: a.order,
274	        reached,
275	        completedThrough,
276	        abandoned,
277	        dropOffRate: reached > 0 ? abandoned / reached : 0,
278	        erroredSessions: a.errored.size,
279	        errorEvents: a.errorEvents,
280	        topErrors,
281	      };
282	    });
283	
284	    out.push({
285	      product,
286	      started: steps[0]?.reached ?? 0,
287	      completed,
288	      erroredSessions: erroredAnywhere.size,
289	      steps,
290	    });
291	  }
292	
293	  return out;
294	}
