1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { PageHeader, StatCard, Badge } from "@/components/ui/primitives";
4	import { MeterBar } from "@/components/ui/charts";
5	import { deployFunnels, type ProductFunnel } from "@/lib/deploy-funnel";
6	
7	export const dynamic = "force-dynamic";
8	
9	const WINDOWS = [7, 30, 90] as const;
10	type Win = (typeof WINDOWS)[number];
11	
12	const PRODUCT_LABEL: Record<string, string> = { vps: "VPS", game: "Game servers", hosting: "Web hosting", email: "Business email" };
13	
14	function pct(n: number, d: number): string {
15	  if (d <= 0) return "0%";
16	  return `${((n / d) * 100).toFixed(n / d >= 0.1 ? 0 : 1)}%`;
17	}
18	
19	function ProductFunnelCard({ f }: { f: ProductFunnel }) {
20	  const max = Math.max(...f.steps.map((s) => s.reached), 1);
21	  return (
22	    <div className="card">
23	      <div className="flex flex-wrap items-baseline justify-between gap-2">
24	        <h2 className="font-semibold">{PRODUCT_LABEL[f.product] ?? f.product}</h2>
25	        <div className="flex flex-wrap gap-3 text-xs text-slate-400">
26	          <span>
27	            Started <span className="font-semibold text-slate-200">{f.started.toLocaleString()}</span>
28	          </span>
29	          <span>
30	            Completed <span className="font-semibold text-emerald-300">{f.completed.toLocaleString()}</span>
31	            <span className="ml-1 text-slate-500">{pct(f.completed, f.started)}</span>
32	          </span>
33	          <span>
34	            Errored <span className="font-semibold text-red-300">{f.erroredSessions.toLocaleString()}</span>
35	          </span>
36	        </div>
37	      </div>
38	      <p className="mt-1 text-xs text-slate-500">
39	        How far each session gets through the wizard. Per step: reached · completed-through · abandoned (drop-off) ·
40	        errored (a bug/provision failure, not just leaving).
41	      </p>
42	
43	      <div className="mt-4 space-y-4">
44	        {f.steps.map((s, i) => (
45	          <div key={s.step}>
46	            <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
47	              <span className="font-medium">
48	                {i + 1}. {s.step}
49	              </span>
50	              <span className="flex flex-wrap items-baseline gap-x-3 gap-y-0.5 justify-end tabular-nums text-xs">
51	                <span className="text-slate-200">
52	                  <span className="font-semibold">{s.reached.toLocaleString()}</span> reached
53	                </span>
54	                <span className="text-emerald-300">{s.completedThrough.toLocaleString()} completed-through</span>
55	                <span className="text-amber-300">
56	                  {s.abandoned.toLocaleString()} abandoned · {pct(s.abandoned, s.reached)}
57	                </span>
58	                {s.erroredSessions > 0 ? (
59	                  <span className="text-red-300">
60	                    {s.erroredSessions.toLocaleString()} errored
61	                    {s.errorEvents > s.erroredSessions ? ` (${s.errorEvents} events)` : ""}
62	                  </span>
63	                ) : (
64	                  <span className="text-slate-600">0 errored</span>
65	                )}
66	              </span>
67	            </div>
68	            <MeterBar value={s.reached} max={max} color={s.erroredSessions > 0 ? "#f87171" : "#8a70fb"} />
69	            {s.topErrors.length > 0 && (
70	              <ul className="mt-1.5 space-y-1 pl-1">
71	                {s.topErrors.map((e, j) => (
72	                  <li key={j} className="flex items-baseline gap-2 text-xs">
73	                    <Badge tone="red">{e.code ?? "error"}</Badge>
74	                    <span className="min-w-0 truncate text-slate-400" title={e.message ?? ""}>
75	                      {e.message ?? "—"}
76	                    </span>
77	                    <span className="shrink-0 tabular-nums text-slate-500">×{e.count}</span>
78	                  </li>
79	                ))}
80	              </ul>
81	            )}
82	          </div>
83	        ))}
84	      </div>
85	    </div>
86	  );
87	}
88	
89	export default async function DeployFunnelPage({
90	  searchParams,
91	}: {
92	  searchParams: Promise<{ days?: string }>;
93	}) {
94	  await requireArea("analytics");
95	
96	  const sp = await searchParams;
97	  const days: Win = WINDOWS.includes(Number(sp.days) as Win) ? (Number(sp.days) as Win) : 30;
98	
99	  const funnels = await deployFunnels(days);
100	
101	  const totalStarted = funnels.reduce((s, f) => s + f.started, 0);
102	  const totalCompleted = funnels.reduce((s, f) => s + f.completed, 0);
103	  const totalErrored = funnels.reduce((s, f) => s + f.erroredSessions, 0);
104	
105	  return (
106	    <div className="space-y-6">
107	      <PageHeader
108	        title="Deploy funnel"
109	        sub="How far customers get through each deploy wizard, and where a drop-off is a BUG (errored) versus an abandonment."
110	      />
111	
112	      <div className="flex gap-2">
113	        {WINDOWS.map((w) => (
114	          <Link
115	            key={w}
116	            href={`/admin/deploy-funnel?days=${w}`}
117	            className={`rounded-lg border px-3 py-1.5 text-sm ${
118	              w === days
119	                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
120	                : "border-white/[0.08] text-slate-400 hover:text-slate-200"
121	            }`}
122	          >
123	            {w}d
124	          </Link>
125	        ))}
126	      </div>
127	
128	      <div className="grid grid-cols-3 gap-4">
129	        <StatCard label="Deploys started" value={totalStarted.toLocaleString()} delta={`all products · ${days}d`} />
130	        <StatCard
131	          label="Deploys completed"
132	          value={totalCompleted.toLocaleString()}
133	          delta={totalStarted > 0 ? `${pct(totalCompleted, totalStarted)} of started` : "no starts yet"}
134	          deltaGood={totalCompleted > 0}
135	        />
136	        <StatCard
137	          label="Sessions with errors"
138	          value={totalErrored.toLocaleString()}
139	          delta="a failed step, not abandonment"
140	          deltaGood={totalErrored === 0}
141	        />
142	      </div>
143	
144	      {funnels.length === 0 ? (
145	        <div className="card">
146	          <p className="py-8 text-center text-sm text-slate-500">
147	            No deploy-wizard activity in this window yet. Events appear here once customers open a deploy wizard
148	            (requires the DeployFunnelEvent table — apply prisma/manual-migration-deploy-funnel.sql).
149	          </p>
150	        </div>
151	      ) : (
152	        <div className="space-y-4">
153	          {funnels.map((f) => (
154	            <ProductFunnelCard key={f.product} f={f} />
155	          ))}
156	        </div>
157	      )}
158	    </div>
159	  );
160	}
