645	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
646	  //     the double-claim race. No token => this order was sold at FULL price, so there
647	  //     is nothing to grant. We deliberately do NOT infer the credit from
648	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
649	  //     order), which would record a redemption for a purchase that never got one.
650	  const walletPromoApplied = !sold && promoCreditCents > 0;
651	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
652	  // Note the intro discount on the billing document (first term only; renews full) —
653	  // ONLY when this specific order actually earned the credit (real customer report:
654	  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
655	  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
656	  // above — and this used to gate on that instead of on whether the credit was
657	  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
658	  // already use to decide whether to grant it).
659	  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
660	  // The checkout coupon settles the same two ways:
661	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
662	  //     throws and surfaces before any money moves if the last slot just went.
663	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
664	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
665	  //     inside the charge tx (never a fresh contended claim — that would double-count the
666	  //     global cap and collide on the per-person unique). No token => full-price order.
667	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
668	
669	  const cap = await capacityCheck(plan.id);
670	  if (!cap.ok) throw new OrderError(cap.reason);
671	
672	  let nodeId: string | null = null;
673	  if (intent.nodeId) {
674	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
675	    if (!n) throw new OrderError("Selected location is not available.");
676	    nodeId = n.id;
677	  } else if (intent.region) {
678	    // Customer picked a region, not a specific node — resolve the actual
679	    // node NOW (least loaded within that region), not from whatever the
680	    // wizard page happened to load. See OrderIntent.region's own comment.
681	    const n = await scheduleNode(plan.ramMB, { region: intent.region, provider: intent.provider });
682	    if (!n) throw new OrderError("That location is at capacity right now — please pick another.");
683	    nodeId = n.id;
684	  } else {
685	    const n = await scheduleNode(plan.ramMB);
686	    nodeId = n?.id ?? null;
687	  }
688	
689	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.

